"use client";

import * as React from "react";
import { Button } from "@/components/ui/button";
import { FallingText } from "@/components/ui/falling-text";
import type { ReferenceTextSize } from "@/lib/cojeev/reference-text-motion";

type Options = { variant?: string; size?: string };

const stageSize = (size?: string): ReferenceTextSize =>
  size === "sm" || size === "lg" ? size : "default";

function Playback({
  children,
  hint = "",
  replayable = true,
}: {
  children: (paused: boolean, replay: number) => React.ReactNode;
  hint?: string;
  replayable?: boolean;
}) {
  const [paused, setPaused] = React.useState(false),
    [replay, setReplay] = React.useState(0);
  return (
    <div style={{ width: "100%", display: "grid", gap: 16, minWidth: 0 }}>
      {children(paused, replay)}
      <div
        style={{
          display: "flex",
          gap: 8,
          flexWrap: "wrap",
          alignItems: "center",
        }}
      >
        <Button
          size="sm"
          variant="outline"
          aria-pressed={paused}
          onClick={() => setPaused((p) => !p)}
        >
          {paused ? "Resume motion" : "Pause motion"}
        </Button>
        {replayable && (
          <Button
            size="sm"
            variant="ghost"
            onClick={() => {
              setReplay((n) => n + 1);
              setPaused(false);
            }}
          >
            Replay
          </Button>
        )}
        {hint && (
          <span style={{ fontSize: 13, color: "var(--v-text-2)" }}>{hint}</span>
        )}
      </div>
    </div>
  );
}

export function FallingTextExample({ variant, size }: Options) {
  return (
    <Playback hint="Word bodies fall, collide and settle inside the page.">
      {(paused, replay) => (
        <FallingText
          text="Let the rigid ways of working fall away."
          gravity={variant === "gentle" ? 500 : 1200}
          size={stageSize(size)}
          paused={paused}
          replayKey={replay}
        />
      )}
    </Playback>
  );
}

export default function Demo() {
  return (
    <FallingTextExample variant="scatter" />
  );
}

```

